import{G as e,K as t,at as n,n as r}from"./chunks/framework.Cv3A6T7g.js";var i=JSON.parse(`{"title":"Securables","description":"","frontmatter":{},"headers":[],"relativePath":"admin/acl/securables.md","filePath":"admin/acl/securables.md"}`),a={name:`admin/acl/securables.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="securables" tabindex="-1">Securables <a class="header-anchor" href="#securables" aria-label="Permalink to “Securables”">​</a></h1><p>Following resources / record types implement <code>securable</code> per-record access.</p><ul><li><code>FAQ</code></li><li><code>Feedback scheme</code></li><li><code>Language</code></li><li><code>Locale</code></li><li><code>Survey scheme</code></li><li><code>Surveys</code></li></ul><p>Securable permissions can be granted / revoked for any specific record in <code>Security</code> tab of the record.</p><p><code>Security</code> tab allows to control:</p><ul><li><a href="#securables">Securables</a><ul><li><a href="#securable-permissions">Securable permissions</a><ul><li><a href="#assigning-users">Assigning users</a></li></ul></li><li><a href="#record-ownership">Record ownership</a></li><li><a href="#record-visibility">Record visibility</a><ul><li><a href="#visibility-types">Visibility types</a><ul><li><a href="#public">Public</a></li><li><a href="#restricted">Restricted</a></li></ul></li></ul></li></ul></li></ul><h2 id="securable-permissions" tabindex="-1">Securable permissions <a class="header-anchor" href="#securable-permissions" aria-label="Permalink to “Securable permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td>browse</td><td>Browse / list record</td></tr><tr><td>read</td><td>Read record details</td></tr><tr><td>edit</td><td>Edit record</td></tr><tr><td>delete</td><td>Delete record</td></tr><tr><td>media</td><td>Control <code>media</code> permissions</td></tr><tr><td>securables</td><td>Control <code>securable</code> permissions</td></tr><tr><td>use</td><td>Control record <code>visibility</code></td></tr><tr><td>[action]</td><td>Specific record action</td></tr></tbody></table><p>Securable access to any record of the resource also gives user the <a href="/admin/acl/resources#resource-access-permission">resource access permission</a>, so the resource section is available in the Admin UI. When last securable access is removed (or the record is deleted) and user doesn&#39;t own any other record of the resource, resource access is removed as well.</p><h3 id="assigning-users" tabindex="-1">Assigning users <a class="header-anchor" href="#assigning-users" aria-label="Permalink to “Assigning users”">​</a></h3><p>User lookup in <code>Security</code> tab searches only users, who can be given the access:</p><ul><li>users with <code>users:browse</code> permission can search by part of name or email</li><li>other users need to enter the <strong>exact email address</strong> of the user</li></ul><p>Survey respondents (users with respondent access only, without any other permission or securable access) are never listed and cannot be given securable access or record ownership.</p><p>Adding user by email, which already belongs to existing user, grants the access to that user instead of creating a new account.</p><p>Users managing securable permissions can only add or remove actions they hold themselves (resource permissions or securable permissions of the record). Removing user&#39;s access completely is only possible if the user doesn&#39;t hold any action, which the managing user doesn&#39;t hold. Record owner can manage all actions.</p><h2 id="record-ownership" tabindex="-1">Record ownership <a class="header-anchor" href="#record-ownership" aria-label="Permalink to “Record ownership”">​</a></h2><p><code>Security</code> also allows to manage ownership of the record. Ownership can be added / modified / removed.</p><p>Ownership can only be changed by the current owner of the record or by users with <code>resource:securables</code> permission. <code>securables</code> securable permission of the record does not allow changing the ownership.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>If user <code>creates new record</code> or <code>copies existing record</code>, user automatically becomes the owner of the record.</p><p>Owner of the record has full access to the record, without the need to grant additional permissions from above table.</p></div><p>Ownership of any record of the resource also gives user the <a href="/admin/acl/resources#resource-access-permission">resource access permission</a>.</p><h2 id="record-visibility" tabindex="-1">Record visibility <a class="header-anchor" href="#record-visibility" aria-label="Permalink to “Record visibility”">​</a></h2><p><code>Security</code> also allows to manage visibility of the record. Visibility can be added / modified / removed.</p><p>It is possible to set record visibility on following resources:</p><ul><li><a href="/admin/system/faqs">FAQ</a></li><li><a href="/admin/system/languages">Languages</a></li><li><a href="/admin/locales/">Locales</a></li><li><a href="/admin/system/feedback-schemes">Feedback schemes</a></li><li><a href="/admin/surveys/schemes">Survey schemes</a></li></ul><h3 id="visibility-types" tabindex="-1">Visibility types <a class="header-anchor" href="#visibility-types" aria-label="Permalink to “Visibility types”">​</a></h3><p>Visibility defines if record can be used, i.e. assigned to other records. For example:</p><ul><li><code>Language</code> can be assigned to <code>Locale</code></li><li><code>Locale</code> can be assigned to <code>Survey</code></li><li><code>FAQ</code> / <code>Feedback scheme</code> / <code>Survey scheme</code> can be assigned to <code>Survey</code></li></ul><h4 id="public" tabindex="-1">Public <a class="header-anchor" href="#public" aria-label="Permalink to “Public”">​</a></h4><p>Public visibility means that record is visible for the use to all users.</p><h4 id="restricted" tabindex="-1">Restricted <a class="header-anchor" href="#restricted" aria-label="Permalink to “Restricted”">​</a></h4><p>Restricted visibility means that record is visible for the use to users</p><ol><li>with <code>resource:use</code> permission granted</li><li>with <code>use</code> securable granted</li></ol>`,32)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};